"""Tic-tac-toe against an unbeatable computer (minimax)."""

LINES = [(0, 1, 2), (3, 4, 5), (6, 7, 8), (0, 3, 6), (1, 4, 7), (2, 5, 8), (0, 4, 8), (2, 4, 6)]


def winner(b):
    for x, y, z in LINES:
        if b[x] != " " and b[x] == b[y] == b[z]:
            return b[x]
    return "draw" if " " not in b else None


def minimax(b, player):
    w = winner(b)
    if w:
        return {"O": 1, "X": -1, "draw": 0}[w], None
    best = (-2, None) if player == "O" else (2, None)
    for i in range(9):
        if b[i] == " ":
            b[i] = player
            score, _ = minimax(b, "X" if player == "O" else "O")
            b[i] = " "
            if (player == "O" and score > best[0]) or (player == "X" and score < best[0]):
                best = (score, i)
    return best


def draw(b):
    rows = [" | ".join(b[r * 3 + c] if b[r * 3 + c] != " " else str(r * 3 + c + 1) for c in range(3)) for r in range(3)]
    print("\n" + "\n---------\n".join(rows) + "\n")


def main():
    board = [" "] * 9
    while not winner(board):
        draw(board)
        text = input("Your move (1-9): ").strip()
        if not text.isdigit() or not 1 <= int(text) <= 9 or board[int(text) - 1] != " ":
            print("Pick an empty square.")
            continue
        board[int(text) - 1] = "X"
        if not winner(board):
            board[minimax(board, "O")[1]] = "O"
    draw(board)
    print({"X": "You win?! That shouldn't happen.", "O": "Computer wins.", "draw": "It's a draw."}[winner(board)])


