"""Roll dice written the tabletop way: 2d6, d20+5, 4d8-1."""
import random
import re

PATTERN = re.compile(r"^(\d*)d(\d+)([+-]\d+)?$")


def roll(text):
    m = PATTERN.match(text.replace(" ", "").lower())
    if not m:
        raise ValueError("Write dice like 2d6 or d20+5.")
    count, sides, bonus = int(m.group(1) or 1), int(m.group(2)), int(m.group(3) or 0)
    if not (1 <= count <= 100 and 2 <= sides <= 1000):
        raise ValueError("Use 1-100 dice with 2-1000 sides.")
    rolls = [random.randint(1, sides) for _ in range(count)]
    return rolls, sum(rolls) + bonus


def main():
    print("Roll dice (like 2d6 or d20+5). q to quit.")
    for example in ("2d6", "d20+5"):
        rolls, total = roll(example)
        print(f"{example}: {rolls} = {total}")
    while True:
        text = input("> ").strip()
        if text.lower() in ("q", ""):
            break
        try:
            rolls, total = roll(text)
            print(f"{rolls} = {total}")
        except ValueError as e:
            print(e)


if __name__ == "__main__":
    try:
        main()
    except (EOFError, KeyboardInterrupt):
        print("\nBye!")

